export const languages = ['en','ar','he'];
export function translate(key, lang, vars) {
  const text = entries[key]?.[languages.indexOf(lang)] ?? entries[key]?.[0] ?? key;
  return vars ? text.replace(/\{(\w+)\}/g, (m, name) => vars[name] ?? m) : text;
}
